    q = r * kq
    # choose p so that discriminant q^2 - 4 p r > 0
    p_max = (q*q - 1) // (4*r)
    if p_max < 1:
        continue
    # keep p moderate but valid
    p_upper_cap = max(1, min(p_max, rng.randint(50, 400)))
    p = rng.randint(1, p_upper_cap)
    d = rng.choice([3,4,5,6])
    # validate difficulty and domain
    N = q // r
    if N < 20:
        continue
    # a should include both 2 and 5 and also an odd factor >1; guaranteed by construction
    if math.gcd(m, 10) != 1 or m <= 1:
        continue
    return {'a': a, 'p': p, 'q': q, 'r': r, 'd': d}
raise RuntimeError('Failed to generate a valid instance after many attempts.')

